#include <vector>
#include <deque>

class Solution {
public:
    int countPartitions(std::vector<int>& nums, int k) {
        int n = nums.size();
        long long MOD = 1000000007;
        std::vector<long long> dp(n + 1, 0), pref(n + 2, 0);
        dp[0] = 1;
        pref[1] = 1;

        std::deque<int> max_dq, min_dq;
        int left = 0;

        for (int right = 0; right < n; ++right) {
            while (!max_dq.empty() && nums[max_dq.back()] <= nums[right]) max_dq.pop_back();
            max_dq.push_back(right);

            while (!min_dq.empty() && nums[min_dq.back()] >= nums[right]) min_dq.pop_back();
            min_dq.push_back(right);

            while (!max_dq.empty() && !min_dq.empty() && (nums[max_dq.front()] - nums[min_dq.front()]) > k) {
                if (max_dq.front() == left) max_dq.pop_front();
                if (min_dq.front() == left) min_dq.pop_front();
                left++;
            }

            long long ways = (pref[right + 1] - pref[left] + MOD) % MOD;
            dp[right + 1] = ways;
            pref[right + 2] = (pref[right + 1] + ways) % MOD;
        }

        return dp[n];
    }
};

import java.util.*;

class Solution {
    public int countPartitions(int[] nums, int k) {
        int n = nums.length;
        long mod = 1000000007L;
        long[] dp = new long[n + 1];
        long[] pref = new long[n + 2];
        dp[0] = 1;
        pref[1] = 1;

        Deque<Integer> maxDq = new ArrayDeque<>();
        Deque<Integer> minDq = new ArrayDeque<>();
        int left = 0;

        for (int right = 0; right < n; right++) {
            while (!maxDq.isEmpty() && nums[maxDq.peekLast()] <= nums[right]) maxDq.pollLast();
            maxDq.addLast(right);

            while (!minDq.isEmpty() && nums[minDq.peekLast()] >= nums[right]) minDq.pollLast();
            minDq.addLast(right);

            while (!maxDq.isEmpty() && !minDq.isEmpty() && (nums[maxDq.peekFirst()] - nums[minDq.peekFirst()]) > k) {
                if (maxDq.peekFirst() == left) maxDq.pollFirst();
                if (minDq.peekFirst() == left) minDq.pollFirst();
                left++;
            }

            long ways = (pref[right + 1] - pref[left] + mod) % mod;
            dp[right + 1] = ways;
            pref[right + 2] = (pref[right + 1] + ways) % mod;
        }

        return (int) dp[n];
    }
}

