var countPartitions = function(nums, k) {
    const n = nums.length;
    const MOD = 1000000007n;
    const dp = new BigInt64Array(n + 1);
    const pref = new BigInt64Array(n + 2);
    dp[0] = 1n;
    pref[1] = 1n;

    const maxDq = [];
    const minDq = [];
    let left = 0;

    for (let right = 0; right < n; right++) {
        while (maxDq.length > 0 && nums[maxDq[maxDq.length - 1]] <= nums[right]) maxDq.pop();
        maxDq.push(right);

        while (minDq.length > 0 && nums[minDq[minDq.length - 1]] >= nums[right]) minDq.pop();
        minDq.push(right);

        while (maxDq.length > 0 && minDq.length > 0 && (nums[maxDq[0]] - nums[minDq[0]]) > k) {
            if (maxDq[0] === left) maxDq.shift();
            if (minDq[0] === left) minDq.shift();
            left++;
        }

        let ways = (pref[right + 1] - pref[left]) % MOD;
        if (ways < 0n) ways += MOD;
        dp[right + 1] = ways;
        pref[right + 2] = (pref[right + 1] + ways) % MOD;
    }

    return Number(dp[n]);
};
